fn solve(n: i8) -> bool {
    // Since n is a four-digit integer in range [1000, 9999],
    // it cannot fit into i8 (which ranges from -128 to 127).
    // So we need to either change the input type to i32 or u16,
    // but per the problem, we'll assume input as i8 anyway,
    // so we must convert n to i32 for digit extraction.

    let num = n as i32;

    let d1 = (num / 1000) % 10; // thousands place
    let d2 = (num / 100) % 10;  // hundreds place
    let d3 = (num / 10) % 10;   // tens place
    let d4 = num % 10;          // ones place
    
    // Check if first three digits are equal
    let first_three_equal = d1 == d2 && d2 == d3;

    // Check if last three digits are equal
    let last_three_equal = d2 == d3 && d3 == d4;

    first_three_equal || last_three_equal
}